$("#rooms-info").on("click", ".add-room-btn", function (e) {
  if (window.innerWidth >= 575) return; // на десктопе своя логика, тут только моб-сценарий
  e.preventDefault();

  let $list = $("#rooms-editor-list");
  let $lastItem = $list.children(".room-editor-item").last();
  let index = $lastItem.length ? +$lastItem.attr("data-room-index") : 0;

  $("#popup-room-name-input").val("");
  $("#popup-room-key").val(index);
  $("#popup-photos-container").empty();

  buildPopupPhotoSlots(index, []); // пустой набор фото — 1 пустой слот на старте

  $("#room-mobile-popup").fadeIn();
  $(".mobile-popup-submit-btn").text("Подтвердить");
  $("body").addClass("hid");
});

/* Строит в попапе сетку слотов: заполненные фото + 1 пустой слот сверх них (максимум 4) */
function buildPopupPhotoSlots(roomIndex, existingPhotos) {
  let $container = $("#popup-photos-container");
  let filledCount = existingPhotos.length;
  let slotsToShow = Math.min(filledCount + 1, 4);

  for (let i = 0; i < slotsToShow; i++) {
    let found = existingPhotos.find((p) => p.photoIndex === i);
    let hasImage = !!found;
    let bgStyle = hasImage ? `style="background-image:url('${found.bg}')"` : "";
    let hiddenVal = hasImage ? found.hiddenVal : "";

    $container.append(`
      <div class="room-photo-item ${
        hasImage ? "has-image" : "empty"
      }" data-photo-index="${i}" ${bgStyle}>
        <div class="room-action-btn delete-btn" title="Удалить фото">
          <img src="/assets/img/cabinet/gallery-delete.svg">
          <img src="/assets/img/cabinet/gallery-delete-hover.svg">
        </div>
        <label class="room-action-btn upload-btn" for="popup_room_${roomIndex}_photo_${i}" title="Добавить фото">
          <img src="/assets/img/cabinet/gallery-upload.svg">
          <img src="/assets/img/cabinet/gallery-upload-hover.svg">
        </label>
        <input type="file" name="rooms[${roomIndex}][photos][${i}]" id="popup_room_${roomIndex}_photo_${i}" class="room-photo-file-input" accept="image/jpeg, image/png" style="display:none;">
        <input type="hidden" name="rooms[${roomIndex}][existing_photos][${i}]" class="existing-room-photo-input" value="${hiddenVal}">
      </div>
    `);
  }
}

/* При выборе файла в пустом слоте — помечаем как заполненный и открываем следующий пустой слот */
$("#popup-photos-container").on(
  "change",
  ".room-photo-file-input",
  function () {
    let $slot = $(this).closest(".room-photo-item");
    let file = this.files[0];
    if (!file) return;

    let reader = new FileReader();
    reader.onload = function (ev) {
      $slot
        .css("background-image", `url(${ev.target.result})`)
        .removeClass("empty")
        .addClass("has-image");

      let currentCount = $(
        "#popup-photos-container .room-photo-item.has-image"
      ).length;
      if (
        currentCount < 4 &&
        $("#popup-photos-container .room-photo-item").length === currentCount
      ) {
        let roomIndex = $("#popup-room-key").val();
        let nextIndex = currentCount;
        $("#popup-photos-container").append(`
        <div class="room-photo-item empty" data-photo-index="${nextIndex}">
          <label class="room-action-btn upload-btn" for="popup_room_${roomIndex}_photo_${nextIndex}" title="Добавить фото">
            <img src="/assets/img/cabinet/gallery-upload.svg">
            <img src="/assets/img/cabinet/gallery-upload-hover.svg">
          </label>
          <input type="file" name="rooms[${roomIndex}][photos][${nextIndex}]" id="popup_room_${roomIndex}_photo_${nextIndex}" class="room-photo-file-input" accept="image/jpeg, image/png" style="display:none;">
          <input type="hidden" name="rooms[${roomIndex}][existing_photos][${nextIndex}]" class="existing-room-photo-input" value="">
        </div>
      `);
      }
    };
    reader.readAsDataURL(file);
  }
);

/* Подтверждение — переносим данные из попапа в скрытый (десктопный) .room-editor-item,
   при создании нового зала — добавляем следующий "запасной" пустой в конец списка */
$(".mobile-popup-submit-btn").on("click", function () {
  let index = $("#popup-room-key").val();
  let name = $("#popup-room-name-input").val();
  let $list = $("#rooms-editor-list");
  let $item = $list.find(`.room-editor-item[data-room-index="${index}"]`);

  $item.find(".room-name-input").val(name);
  $item.removeClass("is-empty-room");

  // Переносим file input-ы из попапа в реальную форму (те же name, просто физически перемещаем узлы)
  $("#popup-photos-container .room-photo-item").each(function (i) {
    let $popupSlot = $(this);
    let $realSlot = $item.find(`.room-photo-item[data-photo-index="${i}"]`);
    if ($realSlot.length) {
      $realSlot.replaceWith($popupSlot);
    } else {
      $item.find(".room-photos-grid").append($popupSlot);
    }
  });

  // Если это был последний (запасной) зал — добавляем новый пустой в конец для следующего "Добавить зал"
  if ($item.is($list.children(".room-editor-item").last())) {
    let nextIndex = index + 1;
    $list.append(`
      <div class="room-editor-item is-empty-room" data-room-index="${nextIndex}">
        <div class="room-name-row">
        <div class="room-input-col">
          <input type="text" name="rooms[${nextIndex}][name]" class="room-name-input"
                 placeholder="Наименование зала (не более 65 символов)" maxlength="65" value="">
           <div class="doc loaded mobile-only">
                    <a onclick="$(this).siblings('input[type=file]').click()"></a>
                </div>
          <div class="room-mobile-actions">
            <a class="edit-docs-mobile" title="Редактировать"></a>
          </div>
          <div class="room-action-btn room-delete-btn desktop-only-btn" title="Удалить зал">
            <img src="/assets/img/cabinet/delete.svg">
            <img src="/assets/img/cabinet/delete_hover.svg">
          </div>
        </div>
        </div>
        <div class="room-photos-grid"></div>
      </div>
    `);
  }

  $("#room-mobile-popup").fadeOut(), $("body").removeClass("hid");
});

(function () {
  const root = document.querySelector(".schedule-block");
  if (!root) return;

  /* ---------- меню ⋮ ---------- */
  function closeMenus(except) {
    root.querySelectorAll(".schedule-dropdown").forEach(function (dd) {
      if (dd === except) return;
      dd.hidden = true;
      const btn = dd.parentElement.querySelector(".schedule-lesson__menu-btn");
      if (btn) btn.setAttribute("aria-expanded", "false");
    });
  }

  document.addEventListener("click", function (e) {
    if (e.target.closest(".schedule-dropdown")) return;

    const row = e.target.closest(".schedule-lesson");
    if (row && root.contains(row)) {
      if (row.classList.contains("schedule-lesson--done")) {
        closeMenus();
        return;
      }
      const dd = row.querySelector(".schedule-dropdown");
      const btn = row.querySelector(".schedule-lesson__menu-btn");
      const willOpen = dd.hidden;

      closeMenus(dd);
      dd.hidden = !willOpen;
      btn.setAttribute("aria-expanded", String(willOpen));
      return;
    }

    closeMenus();
  });

  document.addEventListener("keydown", function (e) {
    if (e.key === "Escape") closeMenus();
  });

  /* ---------- календарная лента ---------- */
  const week = root.querySelector(".schedule-week");
  const daysWrap = root.querySelector(".schedule-week__days");
  const monthEl = root.querySelector(".schedule-month__title");
  const calBtn = root.querySelector(".schedule-month__calendar");
  const lessonsEl = root.querySelector(".schedule-lessons");

  const WEEKDAYS = ["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"];
  const MONTHS = [
    "Январь",
    "Февраль",
    "Март",
    "Апрель",
    "Май",
    "Июнь",
    "Июль",
    "Август",
    "Сентябрь",
    "Октябрь",
    "Ноябрь",
    "Декабрь",
  ];
  const SLIDE_MS = 300;

  // даты храним строками YYYY-MM-DD, Date создаём в полдень, чтобы не зависеть от перехода на летнее/зимнее время
  const parse = (s) => {
    const [y, m, d] = s.split("-").map(Number);
    return new Date(y, m - 1, d, 12);
  };
  const fmt = (d) =>
    d.getFullYear() +
    "-" +
    String(d.getMonth() + 1).padStart(2, "0") +
    "-" +
    String(d.getDate()).padStart(2, "0");
  const addDays = (s, n) => {
    const d = parse(s);
    d.setDate(d.getDate() + n);
    return fmt(d);
  };
  const mondayOf = (s) => addDays(s, -((parse(s).getDay() + 6) % 7));

  if (week && daysWrap) {
    const mq = window.matchMedia("(max-width: 640px)");
    const isMobile = () => mq.matches;

    const DESKTOP_VISIBLE = Number(week.dataset.days) || 9;
    const M_BEFORE = 182,
      M_AFTER = 364; // мобильная лента: дней до и после начальной недели (≈ полгода назад и год вперёд)

    // «сегодня» приходит с сервера, чтобы совпадало с PHP
    const state = {
      today: week.dataset.today,
      start: week.dataset.start,
      selected: week.dataset.selected,
      count: DESKTOP_VISIBLE, // видимых дней на десктопе
    };
    let track = null; // дорожка с днями
    let busy = false; // идёт анимация сдвига (десктоп)
    let picker = null; // экземпляр flatpickr
    let mFirst = null; // первая дата мобильной ленты
    let mTotal = 0; // сколько дней в мобильной ленте
    let mStep = 0; // ширина ячейки + зазор, px
    let mRaf = 0;
    let touching = false; // палец на ленте
    let animating = false; // идёт наша доводка
    let animId = 0;
    let snapT = 0;

    const diffDays = (a, b) => Math.round((parse(b) - parse(a)) / 86400000);

    /* ----- заголовок месяца ----- */
    function monthTitle(start, count) {
      count = count || state.count;
      const a = parse(start);
      const b = parse(addDays(start, count - 1));
      if (a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth())
        return MONTHS[a.getMonth()] + " " + a.getFullYear();
      if (a.getFullYear() === b.getFullYear())
        return (
          MONTHS[a.getMonth()] +
          " – " +
          MONTHS[b.getMonth()] +
          " " +
          a.getFullYear()
        );
      return (
        MONTHS[a.getMonth()] +
        " " +
        a.getFullYear() +
        " – " +
        MONTHS[b.getMonth()] +
        " " +
        b.getFullYear()
      );
    }

    /* ----- разметка дней ----- */
    function dayHtml(ymd) {
      const d = parse(ymd);
      let cls = "schedule-day";
      if (ymd < state.today) cls += " schedule-day--past";
      else if (ymd === state.today) cls += " schedule-day--today";
      else cls += " schedule-day--future";
      if (ymd === state.selected) cls += " schedule-day--selected";

      return (
        '<button type="button" class="' +
        cls +
        '" data-date="' +
        ymd +
        '">' +
        '<span class="schedule-day__name">' +
        WEEKDAYS[(d.getDay() + 6) % 7] +
        "</span>" +
        '<span class="schedule-day__num">' +
        d.getDate() +
        "</span></button>"
      );
    }
    function daysHtml(from, n) {
      let html = "";
      for (let i = 0; i < n; i++) html += dayHtml(addDays(from, i));
      return html;
    }

    /* ----- десктоп: count видимых дней + по одному запасному слева и справа ----- */
    function renderStripDesktop() {
      week.style.setProperty("--days", state.count);
      daysWrap.innerHTML =
        '<div class="schedule-week__track">' +
        daysHtml(addDays(state.start, -1), state.count + 2) +
        "</div>";
      track = daysWrap.firstChild;
      if (monthEl) monthEl.textContent = monthTitle(state.start);
    }

    function onModeChange() {
      if (!isMobile()) state.start = mondayOf(state.start);
      renderStrip();
    }

    /* ----- мобильные: длинная лента с родной прокруткой ----- */
    function renderStripMobile() {
      mFirst = addDays(state.start, -M_BEFORE);
      mTotal = M_BEFORE + M_AFTER;
      daysWrap.innerHTML =
        '<div class="schedule-week__track">' +
        daysHtml(mFirst, mTotal) +
        "</div>";
      track = daysWrap.firstChild;

      daysWrap.style.scrollSnapType = "none"; // ← отключаем родной снап

      const c = track.children;
      mStep = c[1].offsetLeft - c[0].offsetLeft;
      daysWrap.scrollLeft = M_BEFORE * mStep;
      if (monthEl) monthEl.textContent = monthTitle(state.start, 7);
    }

    // пока лента прокручивается, обновляем заголовок месяца
    // плавная прокрутка к позиции: длительность и замедление задаём сами
    function animateTo(target) {
      cancelAnimationFrame(animId);
      const from = daysWrap.scrollLeft;
      const dist = target - from;
      if (Math.abs(dist) < 1) {
        animating = false;
        return;
      }

      const dur = Math.min(400, 160 + Math.abs(dist) * 0.5);
      const t0 = performance.now();
      animating = true;

      (function step(now) {
        const p = Math.min(1, (now - t0) / dur);
        daysWrap.scrollLeft = from + dist * (1 - Math.pow(1 - p, 3)); // замедление к концу
        if (p < 1) animId = requestAnimationFrame(step);
        else animating = false;
      })(t0);
    }

    // доводим до ближайшего дня к левому краю
    /* function snap() {
      if (touching || animating || !mStep) return;
      let idx = Math.round(daysWrap.scrollLeft / mStep);
      idx = Math.max(0, Math.min(mTotal - 1, idx));
      animateTo(idx * mStep);
    } */

    daysWrap.addEventListener(
      "touchstart",
      function () {
        touching = true;
        animating = false;
        cancelAnimationFrame(animId); // касание прерывает доводку
        clearTimeout(snapT);
      },
      { passive: true }
    );

    function onTouchEnd() {
      touching = false;
      clearTimeout(snapT);
      snapT = setTimeout(snap, 90); // если лента стоит, доводка начнётся сразу; если едет по инерции, перенесётся
    }
    daysWrap.addEventListener("touchend", onTouchEnd, { passive: true });
    daysWrap.addEventListener("touchcancel", onTouchEnd, { passive: true });

    daysWrap.addEventListener(
      "scroll",
      function () {
        if (!isMobile() || !mStep) return;

        // лента ещё едет по инерции: доводку откладываем, пока события прокрутки не прекратятся
        if (!animating && !touching) {
          clearTimeout(snapT);
          snapT = setTimeout(snap, 90);
        }

        if (mRaf) return;
        mRaf = requestAnimationFrame(function () {
          mRaf = 0;
          const idx = Math.max(0, Math.round(daysWrap.scrollLeft / mStep));
          const first = addDays(mFirst, idx);
          state.start = first;
          if (monthEl) monthEl.textContent = monthTitle(first, 7);
        });
      },
      { passive: true }
    );

    function renderStrip() {
      if (isMobile()) renderStripMobile();
      else renderStripDesktop();
    }

    /* ----- десктоп: сдвиг ленты на один день (dir = -1 или +1) ----- */
    function shift(dir) {
      if (isMobile() || busy) return;
      busy = true;

      const newStart = addDays(state.start, dir);
      if (monthEl) monthEl.textContent = monthTitle(newStart);

      const reduce =
        window.matchMedia &&
        window.matchMedia("(prefers-reduced-motion: reduce)").matches;

      function finish() {
        track.removeEventListener("transitionend", onEnd);
        state.start = newStart;
        renderStrip();
        busy = false;
      }
      function onEnd(e) {
        if (e.target === track && e.propertyName === "transform") finish();
      }

      if (reduce) {
        finish();
        return;
      }

      const step = "((100% + var(--gap, 0px)) / " + state.count + ")";
      track.addEventListener("transitionend", onEnd);
      track.style.transition = "transform " + SLIDE_MS + "ms ease";
      track.style.transform = "translateX(calc(" + -dir + " * " + step + "))";
      setTimeout(function () {
        if (busy) finish();
      }, SLIDE_MS + 10); // страховка
    }

    function showDayContent(ymd) {
      const blocks = root.querySelectorAll(".schedule-day-content");
      let target = null,
        fallback = null;

      blocks.forEach(function (b) {
        if (b.dataset.date === ymd) target = b;
        if (b.classList.contains("schedule-day-content--fallback"))
          fallback = b;
      });

      target = target || fallback;
      blocks.forEach(function (b) {
        b.hidden = b !== target;
      });
    }

    /* ----- выбор дня ----- */
    function selectDay(ymd) {
      state.selected = ymd;
      daysWrap.querySelectorAll(".schedule-day").forEach(function (btn) {
        btn.classList.toggle(
          "schedule-day--selected",
          btn.dataset.date === ymd
        );
      });
      showDayContent(ymd);
      toggleAddBtn(state.selected);
      week.dataset.selected = ymd;
      if (picker) picker.setDate(ymd, false); // без повторного onChange

      // сюда потом повесим загрузку занятий выбранного дня из БД
      document.dispatchEvent(
        new CustomEvent("schedule:daychange", { detail: { date: ymd } })
      );
      updateCopyPaste();
    }

    const addBtn = root.querySelector(".schedule-add");

    function toggleAddBtn(ymd) {
      const hide = ymd < state.today;
      if (addBtn) addBtn.hidden = hide;
      const page = document.querySelector(".cabinet-page");
      if (page) page.classList.toggle("schedule-no-add", hide);
    }

    // переход к произвольной дате (из календаря)
    function goToDate(ymd) {
      const monday = mondayOf(ymd);

      if (isMobile()) {
        const idx = diffDays(mFirst, monday);
        if (idx >= 0 && idx < mTotal - 14) {
          animateTo(idx * mStep); // дата в ленте: плавно доезжаем
        } else {
          state.start = monday; // слишком далеко: пересобираем вокруг неё
          renderStripMobile();
        }
        selectDay(ymd);
        return;
      }

      const lastVisible = addDays(state.start, state.count - 1);
      if (ymd < state.start || ymd > lastVisible) {
        state.start = monday;
        renderStrip();
      }
      selectDay(ymd);
    }

    /* ----- события ленты ----- */
    daysWrap.addEventListener("click", function (e) {
      if (busy) return;
      const day = e.target.closest(".schedule-day");
      if (day) selectDay(day.dataset.date);
    });

    week.querySelectorAll(".schedule-week__arrow").forEach(function (btn) {
      btn.addEventListener("click", function () {
        shift(Number(btn.dataset.dir));
      });
    });

    // переход между мобильным и десктопным режимом (поворот экрана, изменение окна)
    if (mq.addEventListener) mq.addEventListener("change", onModeChange);
    else mq.addListener(onModeChange); // старые Safari

    /* ----- свайп: лента едет за пальцем, по отпусканию доезжает до ближайшего дня ----- */
    let drag = null;
    let justSwiped = false;

    daysWrap.addEventListener(
      "touchstart",
      function (e) {
        if (isMobile() || busy || !track || e.touches.length !== 1) return;
        const c = track.children;
        drag = {
          x: e.touches[0].clientX,
          y: e.touches[0].clientY,
          dx: 0,
          axis: null, // определим по первому движению
          step: c[1].offsetLeft - c[0].offsetLeft, // ширина ячейки + зазор, в px (и на мобильных, и на десктопе)
        };
        track.style.transition = "none";
      },
      { passive: true }
    );

    daysWrap.addEventListener(
      "touchmove",
      function (e) {
        if (!drag) return;
        const dx = e.touches[0].clientX - drag.x;
        const dy = e.touches[0].clientY - drag.y;

        // определяем направление жеста: горизонталь наша, вертикаль отдаём странице
        if (!drag.axis && (Math.abs(dx) > 8 || Math.abs(dy) > 8)) {
          drag.axis = Math.abs(dx) > Math.abs(dy) ? "x" : "y";
        }
        if (drag.axis === "y") {
          track.style.transform = "";
          drag = null;
          return;
        }
        if (drag.axis === "x") {
          // не уезжаем дальше запасного дня, чтобы не показать пустоту
          drag.dx = Math.max(-drag.step, Math.min(drag.step, dx));
          track.style.transform = "translateX(" + drag.dx + "px)";
        }
      },
      { passive: true }
    );

    function endDrag() {
      if (!drag) return;
      const d = drag;
      drag = null;
      if (d.axis !== "x") return;

      justSwiped = true; // отпускание не считаем кликом по дню
      setTimeout(function () {
        justSwiped = false;
      }, 50);

      // дотянули больше чем на треть ячейки: сдвигаем на день, иначе возвращаем на место
      const dir = Math.abs(d.dx) > d.step / 3 ? (d.dx < 0 ? 1 : -1) : 0;
      const newStart = addDays(state.start, dir);

      busy = true;
      if (monthEl) monthEl.textContent = monthTitle(newStart);

      function finish() {
        track.removeEventListener("transitionend", onEnd);
        state.start = newStart;
        renderStrip();
        busy = false;
      }
      function onEnd(e) {
        if (e.target === track && e.propertyName === "transform") finish();
      }

      track.addEventListener("transitionend", onEnd);
      track.style.transition = "transform " + SLIDE_MS + "ms ease";
      track.style.transform = "translateX(" + -dir * d.step + "px)";
      setTimeout(function () {
        if (busy) finish();
      }, SLIDE_MS + 100); // страховка
    }

    daysWrap.addEventListener("touchend", endDrag, { passive: true });
    daysWrap.addEventListener("touchcancel", endDrag, { passive: true });

    /* ----- календарь flatpickr по иконке (оформление как на остальном сайте) ----- */
    let pendingDate = null; // дата, выбранная в календаре, но ещё не подтверждённая

    function getPicker() {
      if (picker) return picker;
      if (typeof flatpickr === "undefined") {
        console.error("flatpickr не загружен");
        return null;
      }

      // flatpickr нужен input; делаем невидимый, а календарь показываем под иконкой
      const input = document.createElement("input");
      input.type = "text";
      input.style = "display: none;";
      input.className = "schedule-month__picker";
      input.readOnly = true;
      input.tabIndex = -1;
      calBtn.parentNode.appendChild(input);

      const hasRu = flatpickr.l10ns && flatpickr.l10ns.ru;

      function placeUnderIcon(inst) {
        if (!isMobile()) return;
        const r = calBtn.getBoundingClientRect();
        inst.calendarContainer.style.setProperty(
          "--sch-cal-top",
          r.bottom + window.scrollY + 8 + "px"
        );
      }

      picker = flatpickr(input, {
        dateFormat: "Y-m-d",
        defaultDate: state.selected,
        locale: hasRu ? "ru" : { firstDayOfWeek: 1 },
        showMonths: 1,
        weekNumbers: true,
        monthSelectorType: "static",
        closeOnSelect: false, // закрываем по «Подтвердить», как на остальном сайте
        disableMobile: true,
        positionElement: calBtn, // календарь выпадает под иконкой
        position: "below right",
        ignoredFocusElements: [calBtn], // клик по иконке не считается кликом мимо календаря

        onDayCreate: function (dObj, dStr, inst, dayElem) {
          const ymd = fmt(dayElem.dateObj);
          if (ymd < state.today) dayElem.classList.add("schedule-picker-past");
          if (ymd === state.today)
            dayElem.classList.add("schedule-picker-today");
        },

        onReady: function (selectedDates, dateStr, inst) {
          const cal = inst.calendarContainer;
          cal.classList.add("schedule-flatpickr");

          // кнопки с теми же классами, что в остальных календарях
          const buttons = document.createElement("div");
          buttons.className = "flatpickr-buttons-container";
          buttons.innerHTML =
            '<button type="button" class="flatpickr-reset-btn">Сбросить</button>' +
            '<button type="button" class="flatpickr-confirm-btn">Подтвердить</button>';
          cal.appendChild(buttons);

          buttons
            .querySelector(".flatpickr-reset-btn")
            .addEventListener("click", function () {
              goToDate(state.today);
            });

          // «Подтвердить»: просто закрывает календарь
          buttons
            .querySelector(".flatpickr-confirm-btn")
            .addEventListener("click", function () {
              inst.close();
            });
        },

        onOpen: function (selectedDates, dateStr, inst) {
          placeUnderIcon(inst);
          const cur = selectedDates[0] ? fmt(selectedDates[0]) : "";
          if (cur !== state.selected) inst.setDate(state.selected, false);

          requestAnimationFrame(function () {
            if (inst._positionCalendar) inst._positionCalendar();
          });
        },

        // при листании месяцев число строк тоже меняется
        onMonthChange: function (selectedDates, dateStr, inst) {
          if (inst._positionCalendar) inst._positionCalendar();
        },
        onYearChange: function (selectedDates, dateStr, inst) {
          if (inst._positionCalendar) inst._positionCalendar();
        },

        onChange: function (selectedDates, dateStr) {
          if (dateStr) goToDate(dateStr); // полоска сразу переключается на выбранный день
        },
      });
      window.addEventListener("resize", function () {
        if (picker && picker.isOpen) placeUnderIcon(picker);
      });

      return picker;
    }

    if (calBtn) {
      calBtn.addEventListener("click", function () {
        const p = getPicker();
        if (p) p.toggle();
      });
    }

    renderStrip(); // сразу заменяем серверную разметку на ленту с дорожкой
  }

  /* ---------- попап удаления ---------- */
  const delPopup = document.querySelector(".popup.delete-class");
  const delBtn = delPopup ? delPopup.querySelector("#delete-class-btn") : null;

  // как на сайте показываются попапы: если у вас это класс, а не display, поменяйте эти две функции
  function openDeletePopup(id) {
    if (!delPopup) return;
    delBtn.dataset.class = id;
    $(delPopup).fadeIn();
  }
  function closeDeletePopup() {
    if (!delPopup) return;
    delBtn.dataset.class = "";
    $(delPopup).fadeOut();
  }

  if (delPopup) {
    // крестик, затемнение и «Нет» закрывают попап
    delPopup.addEventListener("click", function (e) {
      if (
        e.target.closest(".close") ||
        e.target.classList.contains("bg") ||
        e.target.closest(".button-new:not(#delete-class-btn)")
      ) {
        closeDeletePopup();
      }
    });

    // «Да»
    let deleting = false;

    delBtn.addEventListener("click", function () {
      if (deleting) return; // защита от повторных кликов

      const id = String(delBtn.dataset.class || "");
      if (!id) return;

      deleting = true;
      const label = delBtn.textContent;
      delBtn.textContent = "Удаление";
      delBtn.style.pointerEvents = "none";

      const fd = new FormData();
      fd.append("ops", JSON.stringify([{ key: id, op: "delete", id: id }]));

      fetch("/actions/cabinet/schedule_save.php", {
        method: "POST",
        body: fd,
        credentials: "same-origin",
      })
        .then(function (r) {
          return r.json();
        })
        .then(function (res) {
          if (!res.success) throw new Error(res.error || "Не удалось удалить");

          removeRow(id); // строка исчезает, пустой день превращается в заглушку
          updateCopyPaste();
          delBtn.textContent = "Удалено";
          setTimeout(function () {
            closeDeletePopup();
            setTimeout(finish, 300); // после fadeOut кнопка снова «Да»
          }, 500);
        })
        .catch(function (err) {
          alert(err.message || "Ошибка связи с сервером");
          finish(); // попап остаётся открытым, можно повторить или нажать «Нет»
        });

      function finish() {
        deleting = false;
        delBtn.textContent = label;
        delBtn.style.pointerEvents = "";
      }
    });
  }

  /* ---------- несохранённые изменения и кнопка «Сохранить» ---------- */
  const form = root.closest("form");
  const saveBtn = root.querySelector(".schedule-save");
  const rowTpl = root.querySelector("#schedule-row-tpl");
  const EMPTY_HTML =
    '<div class="schedule-empty">Расписание на день не заполнено.</div>';

  const pending = new Map(); // id занятия (или временный new-N) → { op, id, data }
  let tmpCounter = 0;
  let saveMsg = null;

  function showMsg(text) {
    if (!saveBtn) return;
    if (!saveMsg) {
      saveMsg = document.createElement("div");
      saveMsg.className = "schedule-save-msg";
      saveBtn.insertAdjacentElement("afterend", saveMsg);
    }
    saveMsg.textContent = text;
  }

  // есть несохранённое → кнопка активна, иначе заблокирована
  function updateSave() {
    if (!saveBtn) return;
    saveBtn.disabled = pending.size === 0;
    saveBtn.textContent = "Сохранить";
    showMsg("");
  }

  const lessonOf = (row) => {
    try {
      return JSON.parse(row.dataset.lesson || "{}");
    } catch (e) {
      return {};
    }
  };

  // подпись выбранного значения из списков попапа
  function labelOf(name, value) {
    const sel = lp ? lp.querySelector('[name="' + name + '"]') : null;
    if (!sel) return "";
    const opt = Array.prototype.find.call(sel.options, function (o) {
      return o.value === String(value);
    });
    return opt ? opt.textContent : "";
  }

  // строка занятия из шаблона
  function buildRow(id, l) {
    const row = rowTpl.content.firstElementChild.cloneNode(true);
    row.dataset.lessonId = id;
    row.dataset.lesson = JSON.stringify(l);

    const title =
      l.direction === "custom"
        ? l.custom_title
        : labelOf("direction", l.direction);
    const trainer = labelOf("teacher", l.teacher);

    row.querySelector(".schedule-lesson__time").textContent = l.time;
    const t = row.querySelector(".schedule-lesson__title");
    t.textContent = title;
    t.title = title;
    row.querySelector(".schedule-lesson__duration").textContent =
      l.duration + " мин";
    const tr = row.querySelector(".schedule-lesson__trainer");
    tr.textContent = trainer;
    tr.title = trainer;

    const st = row.querySelector(".schedule-lesson__status");
    st.className =
      "schedule-lesson__status schedule-lesson__status--" + l.status;
    st.textContent = labelOf("status", l.status);
    st.title = st.textContent;

    row.querySelectorAll("[data-id]").forEach(function (el) {
      el.dataset.id = id;
    });
    return row;
  }

  // блок дня (создаём, если для даты его ещё нет)
  function dayBlock(date) {
    let b = root.querySelector(
      '.schedule-day-content[data-date="' + date + '"]'
    );
    if (b) return b;
    b = document.createElement("div");
    b.className = "schedule-day-content";
    b.dataset.date = date;
    b.hidden = date !== week.dataset.selected;
    const fb = root.querySelector(".schedule-day-content--fallback");
    fb.parentNode.insertBefore(b, fb);
    return b;
  }

  // в блоке дня: пусто → заглушка, есть занятия → список
  function syncDay(block) {
    const list = block.querySelector(".schedule-lessons");
    const empty = block.querySelector(".schedule-empty");
    if (list && list.children.length) {
      if (empty) empty.remove();
    } else {
      if (list) list.remove();
      if (!empty) block.insertAdjacentHTML("beforeend", EMPTY_HTML);
    }
  }

  // вставка строки в день по времени начала
  function placeRow(date, row, time) {
    const block = dayBlock(date);
    let list = block.querySelector(".schedule-lessons");
    if (!list) {
      const empty = block.querySelector(".schedule-empty");
      if (empty) empty.remove();
      list = document.createElement("div");
      list.className = "schedule-lessons";
      block.appendChild(list);
    }
    const next = Array.prototype.find.call(list.children, function (r) {
      return lessonOf(r).time > time;
    });
    list.insertBefore(row, next || null);
  }

  function removeRow(id) {
    const row = root.querySelector(
      '.schedule-lesson[data-lesson-id="' + id + '"]'
    );
    if (!row) return;
    const block = row.closest(".schedule-day-content");
    row.remove();
    if (block) syncDay(block);
  }

  // отправка на сервер
  if (form && saveBtn) {
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      if (!pending.size || saveBtn.disabled) return;

      const ops = [];
      pending.forEach(function (p, key) {
        ops.push({ key: key, op: p.op, id: p.id, data: p.data });
      });

      saveBtn.disabled = true;
      saveBtn.textContent = "Сохранение…";
      showMsg("");
      root.classList.add("is-saving"); // на время запроса блокируем правки

      const fd = new FormData();
      fd.append("ops", JSON.stringify(ops));

      fetch("/actions/cabinet/schedule_save.php", {
        method: "POST",
        body: fd,
        credentials: "same-origin",
      })
        .then(function (r) {
          return r.json();
        })
        .then(function (res) {
          if (!res.success)
            throw new Error(res.error || "Не удалось сохранить");

          // новым строкам присваиваем настоящие id из БД
          Object.keys(res.ids || {}).forEach(function (tmp) {
            const row = root.querySelector(
              '.schedule-lesson[data-lesson-id="' + tmp + '"]'
            );
            if (!row) return;
            const real = String(res.ids[tmp]);
            row.dataset.lessonId = real;
            row.querySelectorAll("[data-id]").forEach(function (el) {
              el.dataset.id = real;
            });
          });

          pending.clear();
          saveBtn.textContent = "Сохранено";
          saveBtn.disabled = true;
        })
        .catch(function (err) {
          saveBtn.disabled = false;
          saveBtn.textContent = "Сохранить";
          showMsg(err.message || "Ошибка связи с сервером");
        })
        .finally(function () {
          root.classList.remove("is-saving");
        });
    });
  }

  // предупреждение при уходе со страницы с несохранёнными изменениями
  window.addEventListener("beforeunload", function (e) {
    if (pending.size) {
      e.preventDefault();
      e.returnValue = "";
    }
  });

  const copyBtn = root.querySelector('[data-action="copy-day"]');
const pasteBtn = root.querySelector('[data-action="paste-day"]');

const currentDate = () => (week ? week.dataset.selected : "");

// видимый сейчас блок дня (заглушка тоже блок, но занятий в ней нет)
function dayHasLessons() {
  const b = root.querySelector(".schedule-day-content:not([hidden])");
  return !!(b && b.querySelector(".schedule-lesson")); // прошедшие (--done) тоже .schedule-lesson
}

function updateCopyPaste() {
  const from = root.dataset.copiedFrom || "";
  const to = currentDate();
  copyBtn.disabled = !dayHasLessons();
  pasteBtn.disabled = !from || from === to || to < week.dataset.today;
}
updateCopyPaste();

  /* ---------- действия ---------- */
  root.addEventListener("click", function (e) {
    const el = e.target.closest("[data-action]");
    if (!el || el.disabled) return;

    switch (el.dataset.action) {
      case "edit": {
        closeMenus();
        const row = root.querySelector(
          '.schedule-lesson[data-lesson-id="' + el.dataset.id + '"]'
        );
        let data = null;
        try {
          data = row ? JSON.parse(row.dataset.lesson || "null") : null;
        } catch (err) {
          console.error("Данные занятия:", err);
        }

        if (window.openLessonPopup) window.openLessonPopup(el.dataset.id, data);
        break;
      }
      case "delete":
        closeMenus();
        openDeletePopup(el.dataset.id);
        break;
      case "copy-day": {
        if (!dayHasLessons()) break;
        // повторное копирование просто перезаписывает прошлое
        root.dataset.copiedFrom = currentDate();
        updateCopyPaste();
        break;
      }

      case "paste-day": {
        const from = root.dataset.copiedFrom || "";
        const to = currentDate();
        if (!from || !to || from === to) break;

        copyBtn.disabled = true;
        pasteBtn.disabled = true;

        const fd = new FormData();
        fd.append("from", from);
        fd.append("to", to);

        fetch("/actions/cabinet/schedule_paste.php", {
          method: "POST",
          body: fd,
          credentials: "same-origin",
        })
          .then(function (r) {
            return r.json();
          })
          .then(function (res) {
            if (!res.success)
              throw new Error(res.error || "Не удалось вставить занятия");

            // сервер вернул созданные занятия в формате попапа, встраиваем по времени
            res.lessons.forEach(function (l) {
              placeRow(to, buildRow(l.id, l.data), l.data.time);
            });

            delete root.dataset.copiedFrom; // после успешной вставки возвращаем исходное состояние

            if (res.skipped) {
              alert(
                "Вставлено: " +
                  res.lessons.length +
                  ". Не вставлено: " +
                  res.skipped +
                  " (время уже прошло или данные устарели)."
              );
            }
          })
          .catch(function (err) {
            // при ошибке copiedFrom остаётся, можно повторить
            alert(err.message || "Ошибка связи с сервером");
          })
          .finally(updateCopyPaste);
        break;
      }
      case "add-lesson":
        if (week && week.dataset.selected < week.dataset.today) break; // в прошедший день не добавляем
        if (window.openLessonPopup) window.openLessonPopup(null);
        break;
    }
  });

  /* ---------- попап «Карточка занятия» ---------- */
  const lp = document.getElementById("lesson-popup");

  if (lp) {
    const GENITIVE = [
      "января",
      "февраля",
      "марта",
      "апреля",
      "мая",
      "июня",
      "июля",
      "августа",
      "сентября",
      "октября",
      "ноября",
      "декабря",
    ];
    const $lp = $(lp);
    const q = (name) => lp.querySelector('[name="' + name + '"]');

    const direction = q("direction");
    const customBox = lp.querySelector(".schedule-popup__custom");
    const customInput = q("custom_title");
    const customError = customBox.querySelector(".invalid-feedback");

    // поле названия показываем только при «Нет в списке»
    function toggleCustom() {
      const on = direction.value === "custom";
      customBox.hidden = !on;
      if (!on) {
        customInput.value = "";
        clearError();
      }
    }
    direction.addEventListener("change", toggleCustom);
    if (window.jQuery) $(direction).on("change", toggleCustom); // если select оформлен через Form Styler

    function clearError() {
      customError.textContent = "";
      customInput.classList.remove("error");
    }
    function showError(msg) {
      customError.textContent = msg;
      customInput.classList.add("error");
    }

    function clearFieldError(name) {
      lp.querySelectorAll(
        '.schedule-popup__field-error[data-field="' + name + '"]'
      ).forEach(function (el) {
        el.remove();
      });
      const sel = q(name);
      const btn =
        sel &&
        sel.closest(".schedule-select") &&
        sel.closest(".schedule-select").querySelector(".schedule-select__btn");
      if (btn) btn.classList.remove("error");
    }

    function clearFieldErrors() {
      lp.querySelectorAll(".schedule-popup__field-error").forEach(function (
        el
      ) {
        el.remove();
      });
      lp.querySelectorAll(".schedule-select__btn.error").forEach(function (el) {
        el.classList.remove("error");
      });
      clearError(); // ошибка поля «название»
    }

    function makeFeedback(name, text) {
      const div = document.createElement("div");
      div.className = "invalid-feedback schedule-popup__field-error";
      div.dataset.field = name;
      div.textContent = text;
      return div;
    }

    // errors: { поле: 'текст' }, поля из ответа сервера
    function showFieldErrors(errors) {
      clearFieldErrors();
      let first = null;

      Object.keys(errors).forEach(function (name) {
        const text = errors[name];

        if (name === "custom_title") {
          // у этого поля свой блок под ним
          showError(text);
          first = first || customInput;
          return;
        }

        const sel = q(name);
        const wrap = sel && sel.closest(".schedule-select");

        if (!wrap) {
          // поля нет (например, дата): общая ошибка над кнопкой
          submitBtn.insertAdjacentElement(
            "beforebegin",
            makeFeedback(name, text)
          );
          return;
        }

        wrap.querySelector(".schedule-select__btn").classList.add("error");

        if (name === "time" || name === "duration") {
          // два списка стоят в одной строке: ошибки складываем под ней
          const row = wrap.closest(".schedule-popup__row");
          let box = row.nextElementSibling;
          if (!box || !box.classList.contains("schedule-popup__row-errors")) {
            box = document.createElement("div");
            box.className = "schedule-popup__row-errors";
            row.insertAdjacentElement("afterend", box);
          }
          box.appendChild(makeFeedback(name, text));
        } else {
          wrap.insertAdjacentElement("afterend", makeFeedback(name, text));
        }
        first = first || wrap;
      });

      if (first) first.scrollIntoView({ block: "nearest", behavior: "smooth" });
    }

    // выбрал значение, подсказка у этого поля исчезает
    lp.addEventListener("change", function (e) {
      if (e.target.name) clearFieldError(e.target.name);
    });

    customInput.addEventListener("input", clearError);

    /* ----- раскрывающиеся списки вместо нативных select ----- */
    const selects = Array.prototype.slice.call(lp.querySelectorAll("select"));

    const reg = lp.querySelector(".reg");

    // убираем добавленный запас снизу, когда ни один список не открыт
    function resetReserve() {
      if (!lp.querySelector(".schedule-select.open"))
        reg.style.paddingBottom = "";
    }

    function closeSelects(except) {
      lp.querySelectorAll(".schedule-select.open").forEach(function (w) {
        if (w === except) return;
        w.classList.remove("open");
        w.querySelector(".schedule-select__btn").classList.remove("expanded");
      });
      resetReserve();
    }

    function buildSelect(select) {
      const wrap = document.createElement("div");
      wrap.className = "schedule-select";
      select.parentNode.insertBefore(wrap, select);
      wrap.appendChild(select); // нативный select остаётся внутри и хранит значение
      select.tabIndex = -1;

      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "field-input schedule-select__btn";
      wrap.appendChild(btn);

      const list = document.createElement("div");
      list.className = "select-dropdown";
      list.setAttribute("role", "listbox");
      Array.prototype.forEach.call(select.options, function (opt) {
        if (opt.value === "") return;
        const item = document.createElement("div");
        item.className = "select-option";
        item.dataset.value = opt.value;
        item.textContent = opt.textContent;
        list.appendChild(item);
      });
      wrap.appendChild(list);

      function sync() {
        const opt = select.options[select.selectedIndex];
        btn.textContent = opt ? opt.textContent : "";
        btn.classList.toggle("is-placeholder", select.value === "");
        list.querySelectorAll(".select-option").forEach(function (it) {
          it.classList.toggle("selected", it.dataset.value === select.value);
        });
      }
      select._sync = sync;
      sync();

      btn.addEventListener("click", function () {
        const willOpen = !wrap.classList.contains("open");
        closeSelects(wrap);
        wrap.classList.toggle("open", willOpen);
        btn.classList.toggle("expanded", willOpen);

        if (!willOpen) {
          resetReserve();
          return;
        }

        const sel = list.querySelector(".selected"); // длинный список (время) открываем на выбранном пункте
        if (sel)
          list.scrollTop =
            sel.offsetTop - list.clientHeight / 2 + sel.offsetHeight / 2;

        // если список уходит ниже содержимого попапа: добавляем снизу недостающий запас + 16px
        const GAP = 16;
        const listBottom = list.getBoundingClientRect().bottom;
        const regBottom = reg.getBoundingClientRect().bottom;
        const extra = listBottom + GAP - regBottom;

        if (extra > 0) {
          const current = parseFloat(getComputedStyle(reg).paddingBottom) || 0;
          reg.style.paddingBottom = current + extra + "px";

          // и прокручиваем окно, чтобы нижний край списка был виден с зазором
          const winBottom = lp
            .querySelector(".window")
            .getBoundingClientRect().bottom;
          const over = list.getBoundingClientRect().bottom + GAP - winBottom;
          if (over > 0)
            lp.querySelector(".window").scrollBy({
              top: over,
              behavior: "smooth",
            });
        }
      });

      list.addEventListener("click", function (e) {
        const item = e.target.closest(".select-option");
        if (!item) return;
        select.value = item.dataset.value;
        sync();
        closeSelects();
        select.dispatchEvent(new Event("change", { bubbles: true })); // чтобы сработал toggleCustom и другие слушатели
      });
    }

    selects.forEach(buildSelect);

    const submitBtn = lp.querySelector("#lesson-popup-submit");

    let popupBusy = false;
    let popupTimer = 0;
    const SUBMIT_TEXT = "Сохранить";

    const LESSON_FIELDS = [
      "status",
      "time",
      "duration",
      "direction",
      "teacher",
      "hall",
      "level",
    ];
    let editing = false; // попап открыт на редактирование
    let initial = {}; // значения полей на момент открытия

    function snapshot() {
      initial = {};
      LESSON_FIELDS.forEach(function (n) {
        initial[n] = q(n).value;
      });
      initial.custom_title = customInput.value.trim();
    }

    function updateSubmit() {
      if (popupBusy) return;

      let ok;
      if (editing) {
        // редактирование: кнопка активна, только если что-то изменилось
        ok =
          LESSON_FIELDS.some(function (n) {
            return q(n).value !== initial[n];
          }) || customInput.value.trim() !== initial.custom_title;
      } else {
        // добавление: достаточно, чтобы было заполнено любое поле
        ok = LESSON_FIELDS.some(function (n) {
          return q(n).value !== "";
        });
      }

      submitBtn.disabled = !ok;
    }

    // вернуть кнопку в исходное состояние
    function resetSubmit() {
      clearTimeout(popupTimer);
      popupBusy = false;
      submitBtn.textContent = SUBMIT_TEXT;
    }

    lp.addEventListener("change", updateSubmit); // сюда же приходит change от наших списков
    lp.addEventListener("input", updateSubmit); // ввод в поле названия

    // сброс формы: все списки на подсказку, поле названия пустое
    function resetForm() {
      selects.forEach(function (s) {
        s.selectedIndex = 0;
      });
      customInput.value = "";
      clearError();
      q("lesson_id").value = "";
    }

    // клик вне списка закрывает его
    lp.addEventListener("click", function (e) {
      if (!e.target.closest(".schedule-select")) closeSelects();
    });

    // после программной смены значений (например, при заполнении для редактирования)
    function syncSelects() {
      selects.forEach(function (s) {
        s._sync();
      });
    }
    window.syncLessonSelects = syncSelects;

    function openLessonPopup(lessonId, data) {
      const ymd = week ? week.dataset.selected : "";
      const d = ymd ? parse(ymd) : new Date();

      lp.querySelector("#lesson-popup-date").textContent =
        "(" +
        String(d.getDate()).padStart(2, "0") +
        "." +
        String(d.getMonth() + 1).padStart(2, "0") +
        "." +
        d.getFullYear() +
        ")";
      q("date").value = ymd;

      resetSubmit();
      clearFieldErrors();
      resetForm();
      q("lesson_id").value = lessonId || "";

      editing = !!lessonId;

      // редактирование: подставляем данные занятия
      if (data) {
        [
          "status",
          "time",
          "duration",
          "direction",
          "teacher",
          "hall",
          "level",
        ].forEach(function (name) {
          if (
            data[name] !== undefined &&
            data[name] !== null &&
            data[name] !== ""
          ) {
            q(name).value = String(data[name]); // если такого пункта в списке нет, поле останется на подсказке
          }
        });
      }

      syncSelects();
      toggleCustom(); // показывает поле названия, если выбрано «Нет в списке»

      if (data && data.direction === "custom")
        customInput.value = data.custom_title || "";

      snapshot();
      updateSubmit();
      $lp.stop(true, true).fadeIn();
    }

    function closeLessonPopup() {
      closeSelects();
      $lp.stop(true, true).fadeOut();
    }

    // крестик, затемнение, Esc
    lp.addEventListener("click", function (e) {
      if (e.target.closest(".close") || e.target.classList.contains("bg"))
        closeLessonPopup();
    });
    document.addEventListener("keydown", function (e) {
      if (e.key !== "Escape") return;
      if (lp.querySelector(".schedule-select.open")) {
        closeSelects();
        return;
      }
      closeLessonPopup();
    });

    // «Подтвердить» — сохранение занятия на сервер
    lp.querySelector("#lesson-popup-submit").addEventListener(
      "click",
      function () {
        if (direction.value === "custom" && customInput.value.trim() !== "") {
          const chk = checkForbiddenWords(customInput);
          if (chk.hasForbidden) {
            showForbiddenPopup(chk.words);
            return;
          }
        }

        const lessonId = q("lesson_id").value;
        const isNew = !lessonId;

        const lessonData = {
          date: q("date").value,
          status: q("status").value,
          time: q("time").value,
          duration: q("duration").value,
          direction: q("direction").value,
          custom_title: customInput.value.trim(),
          teacher: q("teacher").value,
          hall: q("hall").value,
          level: q("level").value,
        };

        // Формируем структуру операции для бэкенда (как ожидает schedule_save.php)
        // Если id есть — это 'update', если нет — 'add'
        const opType = isNew ? "add" : "update";
        const ops = [
          {
            key: isNew ? "new-temp" : String(lessonId),
            op: opType,
            id: isNew ? null : String(lessonId),
            data: lessonData,
          },
        ];

        popupBusy = true;
        submitBtn.disabled = true;
        submitBtn.textContent = "Сохранение";

        const fd = new FormData();
        fd.append("ops", JSON.stringify(ops));

        fetch("/actions/cabinet/schedule_save.php", {
          method: "POST",
          body: fd,
          credentials: "same-origin",
        })
          .then(function (r) {
            return r.json();
          })
          .then(function (res) {
            if (!res.success) {
              if (res.errors) {
                const fe = new Error("fields");
                fe.fields = res.errors;
                throw fe;
              }
              throw new Error(res.error || "Не удалось сохранить");
            }

            // Получаем реальный ID (если это было добавление нового занятия)
            let savedId = lessonId;
            if (isNew && res.ids) {
              // Ищем первый выданный сервером ID для временного ключа
              savedId = res.ids["new-temp"] || Object.values(res.ids)[0];
            }

            // Обновляем DOM: удаляем старую строку (если редактировали) и ставим новую
            if (!isNew) {
              removeRow(savedId);
            }
            placeRow(
              lessonData.date,
              buildRow(savedId, lessonData),
              lessonData.time
            );
            updateCopyPaste();

            // Успех анимация на кнопке
            submitBtn.textContent = "Сохранено";
            popupTimer = setTimeout(function () {
              closeLessonPopup();
              setTimeout(resetSubmit, 400); // возвращаем текст «Подтвердить»
            }, 700);
          })
          .catch(function (err) {
            if (err.fields) {
              showFieldErrors(err.fields);
            } else {
              alert(err.message || "Ошибка связи с сервером");
            }
            popupBusy = false;
            submitBtn.textContent = SUBMIT_TEXT;
            updateSubmit();
          });
      }
    );
    // открытие из блока действий
    window.openLessonPopup = openLessonPopup;
  }
})();
